package cl.acis.ordenes.config; import cl.acis.ordenes.exception.*; import jakarta.servlet.http.HttpServletRequest; import org.springframework.stereotype.Component;
@Component public class ActorHeaders { public static final String ID="X-Usuario-Id",ROL="X-Usuario-Rol"; public record Actor(Long id,String rol){} public Actor leer(HttpServletRequest r){String i=r.getHeader(ID),rol=r.getHeader(ROL);if(i==null||rol==null)throw new NoAutorizadoException("Faltan los headers X-Usuario-Id y X-Usuario-Rol");try{return new Actor(Long.valueOf(i),rol.toUpperCase());}catch(NumberFormatException e){throw new NoAutorizadoException("X-Usuario-Id debe ser numérico");}} public void exigir(Actor a,String... permitidos){for(String p:permitidos)if(p.equals(a.rol()))return;throw new ProhibidoException("El rol no puede ejecutar esta acción");}}
